<script>
  import { manageAdminSubscription } from '../../lib/api.js'
  export let users=[]; export let onRefresh
  let filter='new';let selected=null;let days=30;let busy=false;let notice=''
  const rub=v=>`${new Intl.NumberFormat('ru-RU').format(Number(v||0))} ₽`
  $: visible=users.filter(u=>filter==='all'||(filter==='online'?Number(u.online_devices)>0:filter==='inactive'?!u.active:true)).sort((a,b)=>filter==='top'?Number(b.paid_rub)-Number(a.paid_rub):new Date(b.created_at)-new Date(a.created_at))
  async function act(user,action,payload={}){busy=true;notice='';try{await manageAdminSubscription(user.telegram_id,{action,...payload});notice='Изменение сохранено и попадёт в Remnawave ближайшим sync';await onRefresh()}catch(e){notice=`Ошибка: ${e.reason||e.message}`}finally{busy=false}}
</script>
<section class="page"><header><span>КЛИЕНТСКАЯ БАЗА</span><h2>Подписки пользователей</h2><p>Продлевайте, сокращайте, отключайте и перевыпускайте ссылки без терминала.</p></header>
  <nav>{#each [['new','Новые'],['top','Больше заплатили'],['online','Онлайн'],['inactive','Неактивные'],['all','Все']] as item}<button class:active={filter===item[0]} on:click={()=>filter=item[0]}>{item[1]}</button>{/each}</nav>
  {#if notice}<p class="notice">{notice}</p>{/if}
  <div class="list">{#each visible as user}<article class:opened={selected===user.telegram_id}><button class="summary" on:click={()=>selected=selected===user.telegram_id?null:user.telegram_id}><div><b>{user.first_name||user.username||`ID ${user.telegram_id}`}</b><small>@{user.username||'без username'} · оплачено {rub(user.paid_rub)} · до {user.expires_at?new Date(user.expires_at+'Z').toLocaleDateString('ru-RU'):'—'}</small></div><span class:ok={user.active}>{user.active?(Number(user.online_devices)>0?'Онлайн':'Активен'):'Неактивен'}</span></button>
    {#if selected===user.telegram_id}<div class="actions"><label>Дней <input type="number" min="1" max="1095" bind:value={days}/></label><button on:click={()=>act(user,'adjust_days',{days:Number(days)})}>Добавить</button><button on:click={()=>act(user,'adjust_days',{days:-Number(days)})}>Убрать</button><button on:click={()=>act(user,'activate_days',{days:Number(days)})}>Активировать от сегодня</button><button on:click={()=>confirm('Старая ссылка перестанет работать. Создать новую?')&&act(user,'regenerate_url')}>Новая ссылка</button><button class="danger" on:click={()=>confirm('Отключить подписку пользователя?')&&act(user,'disable')}>Отключить</button></div>{/if}
  </article>{/each}</div>
</section>
<style>.page{display:grid;gap:18px;max-width:1080px}.page>header span{color:#80c9f4;font-size:10px;font-weight:900;letter-spacing:.15em}.page h2{margin:8px 0 6px;font-size:30px}.page p{margin:0;color:#7890a5}.page>nav{display:flex;gap:7px}.page>nav button{padding:10px 14px;border:0;border-radius:12px;background:#101b29;color:#7890a5}.page>nav button.active{background:#9bd9ff;color:#07111d}.list{display:grid;gap:7px}.list>article{border:1px solid rgba(255,255,255,.06);border-radius:17px;background:#10141c;overflow:hidden}.summary{box-sizing:border-box;width:100%;display:flex;align-items:center;justify-content:space-between;padding:16px;border:0;background:transparent;color:#edf7ff;text-align:left}.summary div{display:grid;gap:4px}.summary small{color:#70879b}.summary span{padding:7px 10px;border-radius:12px;background:rgba(255,121,121,.08);color:#ff9c9c;font-size:10px;font-weight:900}.summary span.ok{background:rgba(97,216,165,.09);color:#78e1b4}.actions{display:flex;flex-wrap:wrap;gap:7px;padding:12px 16px 16px;border-top:1px solid rgba(255,255,255,.05)}.actions label,.actions button{min-height:39px;border:0;border-radius:11px;padding:0 12px;background:#172535;color:#bde7ff}.actions label{display:flex;align-items:center;gap:8px;color:#8da1b2;font-size:11px}.actions input{width:64px;border:0;background:transparent;color:#fff}.actions button{font-weight:800}.actions button.danger{margin-left:auto;background:rgba(255,100,110,.1);color:#ff9c9c}.notice{padding:11px 14px;border-radius:12px;background:#14283a!important;color:#bde7ff!important}</style>
